import {Chess} from './vendor/chess.js';
import {summarize} from './core.mjs';
const $=id=>document.getElementById(id), pct=n=>(100*n).toFixed(1)+'%', glyph={k:'♚',q:'♛',r:'♜',b:'♝',n:'♞',p:'♟'};
let ghost=null;
let chess=new Chess(),timeline=[],cursor=0,selected=null,flipped=false,color='w',games=[],player='Sample player',sample=true,descending=true,marks=[],arrows=[],drag=null,busy=false,aborter=null,parser=null,parserReject=null,archives=[],archiveUser='',allRaw=[],allComplete=false,engine=null,engineReady=false,enginePaused=false,engineBusy=false,pendingFen=null,activeFen=null,engineLines={},analysisTimer;
const moveObject=u=>({from:u.slice(0,2),to:u.slice(2,4),...(u[4]?{promotion:u[4]}:{})});
function boardHTML(c,mini=false){let html='';for(let y=0;y<8;y++)for(let x=0;x<8;x++){const f=flipped?7-x:x,r=flipped?y+1:8-y,sq='abcdefgh'[f]+r,p=c.get(sq),last=timeline[cursor-1],legal=!mini&&selected?c.moves({square:selected,verbose:true}).some(m=>m.to===sq):false;html+=`<${mini?'div':'button'} class="square ${(f+r)%2===0?'dark':''} ${!mini&&selected===sq?'selected':''} ${!mini&&last&&(last.slice(0,2)===sq||last.slice(2,4)===sq)?'last':''} ${legal?'legal':''} ${legal&&p?'capture':''}" ${mini?'':`data-square="${sq}" aria-label="${sq}${p?' '+(p.color==='w'?'white':'black')+' '+p.type:''}"`}>${p?`<span class="piece ${p.color==='w'?'white':''}">${glyph[p.type]}</span>`:''}${!mini&&x===0?`<span class="coord rankcoord">${r}</span>`:''}${!mini&&y===7?`<span class="coord filecoord">${'abcdefgh'[f]}</span>`:''}</${mini?'div':'button'}>`;}return html;}
function renderBoard(){ $('squares').innerHTML=boardHTML(chess);$('turn').textContent=chess.isCheckmate()?'CHECKMATE':chess.isDraw()?'DRAW':(chess.turn()==='w'?'WHITE':'BLACK')+' TO MOVE'+(chess.isCheck()?' · CHECK':'');$('positionlabel').textContent=cursor?'After '+Math.ceil(cursor/2)+(cursor%2?'. ':'… ')+chess.history().at(-1):'Starting position';const displayTop=flipped?'w':'b';$('topplayer').textContent=color===displayTop?player:'Opponent';$('bottomplayer').textContent=color!==displayTop?player:'Opponent';$('samplesub').textContent=(sample?'Illustrative sample':'Imported repertoire')+' · '+(color==='w'?'White':'Black');$('white').classList.toggle('active',color==='w');$('black').classList.toggle('active',color==='b');const temp=new Chess();$('history').replaceChildren();timeline.forEach((u,i)=>{let m=temp.move(moveObject(u));const b=document.createElement('button');b.textContent=(i%2===0?(i/2+1)+'. ':'')+m.san;b.classList.toggle('active',cursor===i+1);b.onclick=()=>navigate(i+1);$('history').append(b);});$('back').disabled=$('start').disabled=cursor===0;$('next').disabled=$('end').disabled=cursor===timeline.length;drawAnnotations();}
function refresh(){selected=null;marks=[];arrows=[];renderBoard();renderStats();requestAnalysis();}
function navigate(n){cursor=Math.max(0,Math.min(n,timeline.length));chess=new Chess();for(const u of timeline.slice(0,cursor))chess.move(moveObject(u));refresh();}
function play(u){try{const m=chess.move(moveObject(u));if(!m)return;timeline=timeline.slice(0,cursor);timeline.push(m.from+m.to+(m.promotion||''));cursor++;refresh();}catch{}}
async function attempt(from,to){const possible=chess.moves({square:from,verbose:true}).filter(m=>m.to===to);if(!possible.length)return false;let prom='';if(possible.some(m=>m.promotion)){prom=await new Promise(resolve=>{$('promotionoptions').replaceChildren();for(const p of ['q','r','b','n']){let b=document.createElement('button');b.textContent=glyph[p];b.onclick=()=>{$('promotion').close();resolve(p)};$('promotionoptions').append(b);}$('promotion').showModal();$('promotion').oncancel=()=>resolve(null);});if(!prom)return false;}play(from+to+prom);return true;}
function xy(s){let x='abcdefgh'.indexOf(s[0]),y=8-Number(s[1]);if(flipped){x=7-x;y=7-y}return [x*100+50,y*100+50];}
function drawAnnotations(){let svg='<defs>';for(const [name,c]of Object.entries({amber:'#e8ad40',red:'#df6262',blue:'#69a9e5'}))svg+=`<marker id="${name}" markerWidth="3" markerHeight="3" refX="2.3" refY="1.5" orient="auto"><path d="M0,0 L3,1.5 L0,3Z" fill="${c}"/></marker>`;svg+='</defs>';for(const m of marks){const [x,y]=xy(m.s);svg+=`<rect x="${x-50}" y="${y-50}" width="100" height="100" fill="${m.c==='red'?'#df6262':m.c==='blue'?'#69a9e5':'#e8ad40'}" opacity=".55"/>`;}for(const a of arrows){const [x,y]=xy(a.from),[tx,ty]=xy(a.to),dx=Math.abs(tx-x),dy=Math.abs(ty-y),knight=(dx===100&&dy===200)||(dx===200&&dy===100);let points=`${x},${y} `;if(knight)points+=dx>dy?`${tx},${y} `:`${x},${ty} `;points+=`${tx},${ty}`;svg+=`<polyline points="${points}" fill="none" stroke="${a.c==='red'?'#df6262':a.c==='blue'?'#69a9e5':'#e8ad40'}" stroke-width="19" stroke-linecap="round" stroke-linejoin="round" marker-end="url(#${a.c})" opacity=".86"/>`;}$('arrows').innerHTML=svg;}
function squareAt(e){return document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-square]')?.dataset.square;}
$('board').oncontextmenu=e=>e.preventDefault();$('board').onpointerdown=e=>{const sq=squareAt(e);if(!sq)return;e.preventDefault();drag={from:sq,button:e.button,c:e.shiftKey?'red':e.altKey?'blue':'amber',x:e.clientX,y:e.clientY};if(e.button===0){marks=[];arrows=[];drawAnnotations();}};
window.addEventListener('pointermove',e=>{if(!drag)return;const to=squareAt(e);if(drag.button===2&&to&&to!==drag.from){arrows.push({...drag,to});drawAnnotations();arrows.pop();}if(drag.button===0&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>5){const p=chess.get(drag.from);if(!p||p.color!==chess.turn())return;if(!ghost){ghost=document.createElement('div');ghost.className='piece dragghost '+(p.color==='w'?'white':'');ghost.textContent=glyph[p.type];document.body.append(ghost);}ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';}});
window.addEventListener('pointerup',async e=>{ghost?.remove();ghost=null;if(!drag)return;const d=drag;drag=null;const to=squareAt(e);if(!to){drawAnnotations();return;}if(!to)return;if(d.button===2){if(d.from===to){const i=marks.findIndex(m=>m.s===to&&m.c===d.c);if(i>=0)marks.splice(i,1);else marks.push({s:to,c:d.c});}else{const i=arrows.findIndex(a=>a.from===d.from&&a.to===to&&a.c===d.c);if(i>=0)arrows.splice(i,1);else arrows.push({...d,to});}drawAnnotations();return;}if(d.button!==0)return;if(d.from!==to){await attempt(d.from,to);selected=null;}else if(selected&&selected!==to){if(!await attempt(selected,to))selected=chess.get(to)?.color===chess.turn()?to:null;}else selected=selected===to?null:chess.get(to)?.color===chess.turn()?to:null;renderBoard();});
$('squares').addEventListener('keydown',async e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();const s=e.target.dataset.square;if(selected&&selected!==s){await attempt(selected,s);selected=null;}else selected=s;renderBoard();}});
function renderStats(){const s=summarize(games,timeline.slice(0,cursor),color,$('speed').value,+$('horizon').value);$('dbtitle').textContent=chess.turn()===color?'Player’s moves':'Opponent replies';$('gamebadge').textContent=s.matched.toLocaleString()+' games';$('summary').innerHTML=`<div class="stat"><strong>${s.rows.length}</strong><small>next moves</small></div><div class="stat"><strong>${s.total.toLocaleString()}</strong><small>continuing games</small></div><div class="stat"><strong>${s.ended}</strong><small>end here</small></div>`;const key=$('sort').value;const rows=s.rows.sort((a,b)=>(descending?-1:1)*(a[key]-b[key])||b.n-a.n);$('moves').replaceChildren();for(const r of rows){const b=document.createElement('button');b.className='moveRow';b.title=`Play ${r.san}. ${r.win} wins, ${r.draw} draws, ${r.loss} losses for ${player}. ${r.branches} distinct continuations in ${r.n} games.`;b.innerHTML=`<div class="movevalues"><span class="san"></span><span>${pct(r.frequency)}<small>${r.n} games</small></span><span>${pct(r.winrate)}<small>${r.win}W / ${r.draw}D / ${r.loss}L</small></span><span>${r.branches}<small>of ${r.n} games</small></span></div><div class="results"><i class="win" style="width:${r.win/r.n*100}%"></i><i class="draw" style="width:${r.draw/r.n*100}%"></i><i class="loss" style="width:${r.loss/r.n*100}%"></i></div>`;b.querySelector('.san').textContent=r.san;b.onclick=()=>play(r.uci);$('moves').append(b);}if(!rows.length)$('moves').innerHTML='<div class="empty">No recorded continuations on this path. Go back a move, change filters, or import more games. You can still explore with Stockfish.</div>';$('samplewarning').textContent=(sample?'Illustrative sample — not a real player’s record. ':'')+`Win rates are for ${player}. `+(s.total<30?'Small sample: treat these frequencies cautiously.':'Historical frequency is not a prediction.');}
$('sort').onchange=$('horizon').onchange=$('speed').onchange=renderStats;$('order').onclick=()=>{descending=!descending;$('order').textContent=descending?'↓':'↑';renderStats();};for(const [id,c]of [['white','w'],['black','b']])$(id).onclick=()=>{color=c;flipped=c==='b';refresh();};$('flip').onclick=()=>{flipped=!flipped;renderBoard();};$('clear').onclick=()=>{marks=[];arrows=[];drawAnnotations();};$('start').onclick=()=>navigate(0);$('back').onclick=()=>navigate(cursor-1);$('next').onclick=()=>navigate(cursor+1);$('end').onclick=()=>navigate(timeline.length);window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;if(e.key==='ArrowLeft'){e.preventDefault();navigate(cursor-1)}if(e.key==='ArrowRight'){e.preventDefault();navigate(cursor+1)}});$('help').onclick=()=>$('guide').showModal();$('closeguide').onclick=()=>$('guide').close();
function status(t){$('status').textContent=t;}
function setBusy(v){busy=v;for(const id of ['find','scan','import','demo','load'])$(id).disabled=v;$('cancel').hidden=!v;$('progress').hidden=!v;$('username').disabled=v;}
$('cancel').onclick=()=>{aborter?.abort();if(parser){parser.terminate();parser=null;parserReject?.(new DOMException('Aborted','AbortError'));parserReject=null;}setBusy(false);status('Import cancelled. Your previous database is unchanged.');};
async function api(url){for(let i=0;i<4;i++){const r=await fetch(url,{signal:aborter?.signal});if(r.ok)return r.json();if(r.status===404)throw Error('Player not found, or archive unavailable. Check the username.');if(r.status===429||r.status>=500){await new Promise((resolve,reject)=>{const timer=setTimeout(resolve,(i+1)*2000);aborter?.signal.addEventListener('abort',()=>{clearTimeout(timer);reject(new DOMException('Aborted','AbortError'))},{once:true});});continue;}throw Error(`Chess.com returned HTTP ${r.status}. Try again later or import a PGN file.`);}throw Error('Chess.com is temporarily rate-limiting requests. Try again later.');}
function username(){const u=$('username').value.trim().toLowerCase();if(!/^[a-z0-9_-]+$/.test(u))throw Error('Enter a valid Chess.com username first.');return u;}
async function findPlayer(){const u=username();if(archiveUser===u&&archives.length)return u;status('Finding monthly game archives…');const data=await api(`https://api.chess.com/pub/player/${encodeURIComponent(u)}/games/archives`);archives=(data.archives||[]).filter(x=>/^https:\/\/api\.chess\.com\/pub\/player\/[a-z0-9_-]+\/games\/\d{4}\/\d{2}$/i.test(x)).sort();archiveUser=u;allRaw=[];allComplete=false;$('count').max=1000;$('number').removeAttribute('max');$('profile').textContent=`${u} · ${archives.length} monthly archives`;$('rangeinfo').textContent='Exact maximum requires scanning the monthly archives.';if(!archives.length)throw Error('This player has no available completed-game archives.');return u;}
$('lookup').onsubmit=async e=>{e.preventDefault();setBusy(true);aborter=new AbortController();try{await findPlayer();status('Player found. Choose a count and import, or scan the full history.');}catch(e){if(e.name!=='AbortError')status(e.message);}finally{setBusy(false);}};
function countChange(v){v=Math.max(1,Math.floor(Number(v)||1));if(allComplete&&archiveUser===$('username').value.trim().toLowerCase())v=Math.min(v,allRaw.length||1);else $('count').max=Math.max(1000,v);$('count').value=$('number').value=v;$('countlabel').textContent=v.toLocaleString();}
$('count').oninput=e=>countChange(e.target.value);$('number').oninput=e=>countChange(e.target.value);
async function getArchive(url){const db=await openDB();const cached=await dbGet(db,'archive:'+url);const current=new Date().toISOString().slice(0,7).replace('-','/');if(cached&&!url.endsWith(current))return cached;const result=await api(url);const raw=(result.games||[]).filter(g=>g.rules==='chess'&&g.pgn);await dbPut(db,'archive:'+url,raw);return raw;}
async function importGames(full){setBusy(true);aborter=new AbortController();try{const u=await findPlayer();let raw=[];const requested=+$('number').value||300;if(allComplete)raw=allRaw;else{for(let i=archives.length-1;i>=0;i--){aborter.signal.throwIfAborted();status(`Reading archive ${archives.length-i} / ${archives.length} · ${raw.length.toLocaleString()} standard games found…`);$('progress').max=archives.length;$('progress').value=archives.length-i;raw.push(...await getArchive(archives[i]));if(!full&&raw.length>=requested)break;if(i===0){allComplete=true;allRaw=raw;}}}raw=[...new Map(raw.map((g,i)=>[g.uuid||g.url||'row'+i,g])).values()].sort((a,b)=>b.end_time-a.end_time);if(full||allComplete){allRaw=raw;allComplete=true;$('count').max=$('number').max=Math.max(1,raw.length);$('rangeinfo').textContent=`${raw.length.toLocaleString()} available standard games · exact scanned maximum`;if(full)countChange(raw.length);else countChange(requested);}const chosen=raw.slice(0,+$('number').value);if(!chosen.length)throw Error('No standard games available.');aborter.signal.throwIfAborted();await parse(chosen,u); }catch(e){if(e.name!=='AbortError')status(e instanceof TypeError?'Could not reach Chess.com. Your browser or their service may be blocking the request. Retry or import a PGN file.':e.message);}finally{setBusy(false);}}
$('import').onclick=()=>importGames(false);$('scan').onclick=()=>importGames(true);
function parse(raw,u){return new Promise((resolve,reject)=>{parserReject=reject;parser=new Worker('./parser.js',{type:'module'});parser.onerror=e=>{parser?.terminate();parser=null;reject(Error('Could not parse the game database.'))};parser.onmessage=async({data})=>{if(data.progress!==undefined){status(`Parsing games ${data.progress} / ${data.total}…`);$('progress').max=data.total;$('progress').value=data.progress;return;}parser.terminate();parser=null;parserReject=null;games=data.parsed;player=u;sample=false;timeline=[];cursor=0;chess=new Chess();status(`Imported ${games.length.toLocaleString()} games. ${data.skipped} unsupported, unfinished, or invalid games skipped.`);refresh();try{await dbPut(await openDB(),'session',{games,player,sample});}catch{status('Imported games, but browser storage is unavailable. Export your data to keep it.');}resolve();};parser.postMessage({raw,username:u});});}
let dbPromise;function openDB(){return dbPromise||=(new Promise(resolve=>{const r=indexedDB.open('prepboard',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null);}));}function dbGet(db,key){return new Promise(resolve=>{if(!db)return resolve(null);const r=db.transaction('data').objectStore('data').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>resolve(null);});}function dbPut(db,key,value){return new Promise(resolve=>{if(!db)return resolve();const tx=db.transaction('data','readwrite');tx.objectStore('data').put(value,key);tx.oncomplete=()=>resolve();tx.onerror=()=>resolve();});}
function demo(){games=[];player='Sample player';sample=true;const lines=[['e4 e5 Nf3 Nc6 Bb5 a6 Ba4 Nf6 O-O Be7',60,'win'],['e4 e5 Nf3 Nc6 Bb5 a6 Ba4 Nf6 O-O Be7',20,'loss'],['e4 c5 Nf3 d6 d4 cxd4 Nxd4 Nf6 Nc3 a6',25,'win'],['e4 c5 Nf3 Nc6 Bb5 g6 Bxc6 dxc6 d3 Bg7',15,'loss'],['e4 d5 exd5 Qxd5 Nc3 Qa5 d4 Nf6 Nf3 c6',27,'win'],['e4 d5 exd5 Qxd5 Nc3 Qd6 d4 Nf6 Nf3 a6',18,'loss'],['e4 d5 Nc3 d4 Nce2 e5 Nf3 Nc6',5,'draw'],['d4 d5 c4 e6 Nc3 Nf6 Bg5 Be7 e3 O-O',30,'win'],['d4 Nf6 c4 g6 Nc3 Bg7 e4 d6 Nf3 O-O',20,'loss'],['Nf3 d5 g3 Nf6 Bg2 c6 O-O Bf5',15,'draw']];for(const [line,n,outcome]of lines){const c=new Chess();line.split(' ').forEach(m=>c.move(m));const h=c.history({verbose:true});for(let i=0;i<n;i++)for(const side of ['w','b'])games.push({color:side,outcome:side==='w'?outcome:outcome==='win'?'loss':outcome==='loss'?'win':'draw',speed:'blitz',moves:h.map(m=>m.from+m.to+(m.promotion||'')),sans:h.map(m=>m.san),end:0});}timeline=[];cursor=0;chess=new Chess();status('Illustrative sample loaded. Import a player to see real statistics.');refresh();}
$('demo').onclick=demo;$('save').onclick=()=>{const blob=new Blob([JSON.stringify({format:'prepboard-v1',player,sample,games})],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`prepboard-${player.replace(/[^a-z0-9_-]/gi,'-')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};$('load').onclick=()=>$('file').click();$('file').onchange=async e=>{const file=e.target.files[0];if(!file)return;setBusy(true);try{const text=await file.text();if(file.name.endsWith('.pgn')){const u=username();const chunks=text.split(/(?=\[Event\s)/).filter(s=>s.trim());await parse(chunks.map(pgn=>({pgn})),u);}else{const d=JSON.parse(text);if(d.format!=='prepboard-v1'||!Array.isArray(d.games)||typeof d.player!=='string')throw Error('Not a Prepboard export.');for(const g of d.games){if(!['w','b'].includes(g.color)||!['win','draw','loss'].includes(g.outcome)||!Array.isArray(g.moves)||!Array.isArray(g.sans)||g.moves.length!==g.sans.length||!g.moves.every(m=>typeof m==='string'&&/^[a-h][1-8][a-h][1-8][qrbn]?$/.test(m)))throw Error('Invalid game data in export.');}games=d.games;player=d.player;sample=!!d.sample;timeline=[];navigate(0);await dbPut(await openDB(),'session',{games,player,sample});status(`Loaded ${games.length} games from file.`);}}catch(e){status(e.message)}finally{setBusy(false);e.target.value='';}};
function requestAnalysis(){clearTimeout(analysisTimer);$('evaltext').textContent='…';pendingFen=chess.fen();engineLines={};$('preview').hidden=true;$('lines').innerHTML='<p class="tiny">Analyzing this position…</p>';if(enginePaused){$('lines').innerHTML='<p class="tiny">Engine paused. Resume to analyze this position.</p>';return;}if(engineBusy)engine.postMessage('stop');analysisTimer=setTimeout(startSearch,100);}
function startSearch(){if(!engineReady||enginePaused||engineBusy||!pendingFen)return;activeFen=pendingFen;pendingFen=null;engineLines={};if(new Chess(activeFen).isGameOver()){$('lines').textContent='Game over — no legal continuation to analyze.';$('engineStatus').textContent='Stockfish 19 · terminal position';$('evaltext').textContent=new Chess(activeFen).isCheckmate()?'M0':'0.0';return;}engineBusy=true;engine.postMessage('position fen '+activeFen);engine.postMessage('go depth '+$('depth').value);}
function initEngine(){engine=new Worker('./vendor/stockfish-19-lite-single.js');engine.onerror=()=>{$('engineStatus').textContent='Engine unavailable';$('lines').textContent='This browser could not start Stockfish WebAssembly. Reload in a recent Firefox or Chrome.';};engine.onmessage=({data})=>{const line=String(data);if(line==='uciok'){engine.postMessage('setoption name Hash value 32');engine.postMessage('setoption name MultiPV value 3');engine.postMessage('isready');}if(line==='readyok'){engineReady=true;startSearch();}if(line.startsWith('bestmove')){engineBusy=false;if(pendingFen)startSearch();}if(!line.startsWith('info depth')||pendingFen||activeFen!==chess.fen()||enginePaused)return;const pv=line.match(/\spv (.+)/),score=line.match(/score (cp|mate) (-?\d+)/),rank=line.match(/multipv (\d+)/),depth=line.match(/depth (\d+)/);if(!pv||!score)return;const sign=activeFen.split(' ')[1]==='w'?1:-1,value=+score[2]*sign;engineLines[rank?+rank[1]:1]={moves:pv[1].split(' '),type:score[1],value,depth:+depth[1]};$('engineStatus').textContent='Stockfish 19 · depth '+depth[1];renderLines();};engine.postMessage('uci');}
function renderLines(){$('lines').replaceChildren();for(const [rank,l]of Object.entries(engineLines)){const row=document.createElement('div');row.className='engineLine';const badge=document.createElement('span');badge.className='score';badge.textContent=l.type==='mate'?'M'+l.value:(l.value>=0?'+':'')+(l.value/100).toFixed(2);row.append(badge);const pv=document.createElement('div');pv.className='pv';const c=new Chess(activeFen);const base=timeline.slice(0,cursor);const sequence=[];for(const u of l.moves.slice(0,14)){let m;try{m=c.move(moveObject(u));}catch{break;}sequence.push(u);const fen=c.fen(),seq=[...sequence],b=document.createElement('button');b.textContent=m.san;b.onmouseenter=e=>showPreview(fen,m.san,e.target);b.onfocus=e=>showPreview(fen,m.san,e.target);b.onmouseleave=b.onblur=()=>{$('preview').hidden=true};b.onclick=()=>{timeline=[...base,...seq];navigate(timeline.length)};pv.append(b);}row.append(pv);$('lines').append(row);if(rank==='1'){let cp=l.type==='mate'?(l.value>0?2000:-2000):l.value;$('evalwhite').style.height=(50+45*Math.tanh(cp/500))+'%';$('evaltext').textContent=badge.textContent;}}}
function showPreview(fen,label,el){$('miniboard').innerHTML=boardHTML(new Chess(fen),true);$('previewlabel').textContent='Position after '+label;const r=el.getBoundingClientRect();$('preview').style.left=Math.max(8,Math.min(innerWidth-248,r.left-120))+'px';$('preview').style.top=Math.max(8,Math.min(innerHeight-280,r.top-270))+'px';$('preview').hidden=false;}
$('engineToggle').onclick=()=>{enginePaused=!enginePaused;$('engineToggle').textContent=enginePaused?'Resume':'Pause';if(enginePaused){engine?.postMessage('stop');$('engineStatus').textContent='Stockfish 19 · paused';}requestAnalysis();};$('depth').onchange=requestAnalysis;
for(const id of ['sort','depth','horizon','speed','count','username'])$(id).setAttribute('aria-label',({sort:'Sort moves by',depth:'Engine search depth',horizon:'Branch horizon',speed:'Time control',count:'Recent game count',username:'Chess.com username'})[id]);
demo();initEngine();dbGet(await openDB(),'session').then(d=>{if(d&&Array.isArray(d.games)){games=d.games;player=d.player;sample=d.sample;$('username').value=sample?'':player;status(`Restored ${games.length.toLocaleString()} cached games.`);refresh();}});
